steps.starter:
ROOMS = {
    "hall": {
        "name": "Hall",
        "desc": "A dusty hall with a grand staircase.",
        "exits": {"north": "library", "east": "kitchen"},
        "items": ["lamp"],
    },
    "library": {
        "name": "Library",
        "desc": "Shelves of old books line the walls.",
        "exits": {"south": "hall"},
        "items": ["key", "book"],
    },
    "kitchen": {
        "name": "Kitchen",
        "desc": "It smells of old bread. A trapdoor leads down.",
        "exits": {"west": "hall", "down": "cellar"},
        "items": [],
    },
    "cellar": {
        "name": "Cellar",
        "desc": "Dark and damp. Something glints in the corner.",
        "exits": {"up": "kitchen"},
        "items": ["treasure"],
        "locked": True,
    },
}

DIRECTIONS = {"n": "north", "s": "south", "e": "east", "w": "west", "u": "up", "d": "down"}
ALIASES = {"l": "look", "q": "quit", "i": "inventory", "get": "take"}
FILLER = {"the", "to", "a", "an"}


def parse(line):
    words = [w for w in line.lower().split() if w not in FILLER]
    if not words:
        return "", ""
    verb, *rest = words
    verb = ALIASES.get(verb, verb)
    verb = DIRECTIONS.get(verb, verb)
    if verb in DIRECTIONS.values():
        return "go", verb
    noun = " ".join(rest)
    if verb == "go":
        noun = DIRECTIONS.get(noun, noun)
    return verb, noun


def read_command():
    try:
        return parse(input())
    except EOFError:
        return "quit", ""


def describe(room_id):
    room = ROOMS[room_id]
    print(f"== {room['name']} ==")
    print(room["desc"])
    print("Exits: " + ", ".join(sorted(room["exits"])))


current = "hall"
describe(current)
while True:
    verb, noun = read_command()
    match verb, noun:
        case "", _:
            continue
        case "look", "":
            describe(current)
        case "go", "":
            print("Go where?")
        case "go", direction:
            exits = ROOMS[current]["exits"]
            if direction in exits:
                current = exits[direction]
                describe(current)
            else:
                print("You can't go that way.")
        case "quit", _:
            print("Bye.")
            break
        case _:
            print("I don't understand.")
